from taf.internal.aashell import AaShellFactory
from contextlib import contextmanager
from . import bip_config
from .tools import python_log


def get_aashell_factory_configuration(gnb_id=0):
    configuration = {}
    hops = bip_config.get_oam_ssh_connection(gnb_id)

    config = {'host': '127.0.0.1',
              'port': 15007,
              'hops': hops}

    for parameter_name, parameter_value in config.items():
        if parameter_name in ["host", "port", "hops", "forwarding_port"]:
            if parameter_value is not None:
                configuration[parameter_name] = int(parameter_value) \
                    if parameter_name in ["port", "forwarding_port"] else parameter_value

    return configuration


@contextmanager
def aashell(gnb_id):
    config = get_aashell_factory_configuration(gnb_id)
    aashell = AaShellFactory().create_aashell(**config)
    aashell.setup()
    yield aashell
    aashell.teardown()


@python_log
def get_aashell_tags(gnb_id):
    output = ""
    command = 'tag -a'
    timeout = 10

    with aashell(gnb_id) as aashell_cli:
        output = aashell_cli.execute(command=command.encode('utf-8'),
                                     timeout=float(timeout)).decode('utf-8')
    return output


@python_log
def is_l1_bypass(gnb_id=0):
    output = get_aashell_tags(gnb_id)
    filtered = [x for x in output.split('\r\n') if 'L1BypassMap' in x]
    return bool(filtered)


@python_log
def get_l1_type(gnb_id=0):
    if gnb_id not in bip_config.BIP_CONFIG:
        bip_config.BIP_CONFIG[gnb_id] = {}
    if 'l1_type' in bip_config.BIP_CONFIG[gnb_id]:
        return bip_config.BIP_CONFIG[gnb_id]['l1_type']

    is_l1b = is_l1_bypass(gnb_id)

    l1_type = "L1b" if is_l1b else "FS"
    bip_config.BIP_CONFIG[gnb_id]['l1_type'] = l1_type
    return l1_type
